contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address target, uint256 mintedAmount) public payable {
        // record before-values
        uint256 beforeTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 beforeBalTarget = c.balanceOf(target); if (__ESBMC_reverted()) return;

        // attempt mint and observe revert
        bool reverted;
        c.mintToken(target, mintedAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 afterBalTarget = c.balanceOf(target); if (__ESBMC_reverted()) return;

        // If mint succeeded then totalSupply and target balance must each increase by mintedAmount.
        // If mint reverted then caller (this contract) must not be owner. We observe owner via public getter.
        address owner = c.owner(); if (__ESBMC_reverted()) return;
        bool callerIsOwner = (owner == address(this));

        assert(
            (!reverted && afterTotal == beforeTotal + mintedAmount && afterBalTarget == beforeBalTarget + mintedAmount)
            || (reverted && !callerIsOwner)
        );
    }
    receive() external payable { }
}

